script:
(function () {
  'use strict';
  // Maximum mortgage (loan amount) from income, debts and debt-to-income (DTI) limits.
  //   Housing budget H = min(front% x monthly income, back% x monthly income - other monthly debts).
  //   P&I budget = H - (property tax + insurance + HOA + mortgage insurance), all monthly.
  //   Maximum loan = P&I x (1 - (1 + i)^-n) / i, i = rate / 12, n = years x 12 (P&I x n at 0%).
  // Checked in Node (scratchpad tests/w3b3_mxm.test.js) against an independent Python computation:
  //   $100,000 income, $500 debts, 28/36, $550/mo tax + insurance, 6.5%, 30 yrs -> budget $2,333.33,
  //   P&I $1,783.33, max loan $282,142.63 (the standard $1,896.20 payment on $300,000 inverts back to $299,999.36, i.e. $300,000 before payment rounding);
  //   back-end binds once debts exceed $666.67; a budget that tax and insurance use up shows $0;
  //   0% rate gives P&I x n; blank or invalid input shows an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var PRESETS = { conventional: [28, 36], fha: [31, 43] };

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function maxLoan(piBudget, rate, years) {
    if (!(piBudget > 0)) return 0;
    var i = rate / 100 / 12, n = years * 12;
    if (i === 0) return piBudget * n;
    return piBudget * (1 - Math.pow(1 + i, -n)) / i;
  }

  function syncPreset(e) {
    var t = e && e.target ? e.target.id : '';
    if (t === 'mxmPreset') {
      var p = PRESETS[el('mxmPreset').value];
      if (p) { el('mxmFront').value = String(p[0]); el('mxmBack').value = String(p[1]); }
    } else if (t === 'mxmFront' || t === 'mxmBack') {
      var f = read('mxmFront'), b = read('mxmBack'), match = 'custom';
      Object.keys(PRESETS).forEach(function (k) { if (PRESETS[k][0] === f && PRESETS[k][1] === b) match = k; });
      el('mxmPreset').value = match;
    }
  }

  function clearResults() {
    ['mxmLoan', 'mxmPI', 'mxmHousing', 'mxmTotal', 'mxmBinding', 'mxmMonthlyInc', 'mxmFrontCap', 'mxmBackCap', 'mxmBudget',
     'mxmCosts', 'mxmPI2'].forEach(function (id) { setText(id, '–'); });
    el('mxmGrid').innerHTML = '';
  }

  function update(e) {
    syncPreset(e);
    var income = read('mxmIncome'), debts = read('mxmDebts', true), rate = read('mxmRate'), term = parseInt(el('mxmTerm').value, 10),
        tax = read('mxmTax', true), ins = read('mxmIns', true), hoa = read('mxmHoa', true), mi = read('mxmMi', true),
        front = read('mxmFront'), back = read('mxmBack');
    var error = el('mxmError'), msg = '';
    if (isNaN(income) || income <= 0) msg = 'Enter your gross annual household income.';
    else if (isNaN(debts) || debts < 0) msg = 'Monthly debts cannot be negative.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (!(term > 0)) msg = 'Choose a loan term.';
    else if ([tax, ins, hoa, mi].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Tax, insurance, HOA dues and mortgage insurance cannot be negative.';
    else if (isNaN(front) || isNaN(back) || front <= 0 || back <= 0 || front > 100 || back > 100) msg = 'Enter front-end and back-end ratios between 1% and 100%.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var mInc = income / 12;
    var frontCap = front / 100 * mInc, backCap = back / 100 * mInc - debts;
    var budget = Math.min(frontCap, backCap);
    var costs = tax + ins + hoa + mi;
    var piBudget = Math.max(0, budget - costs);
    var loan = maxLoan(piBudget, rate, term);

    setText('mxmLoan', money0.format(loan));
    setText('mxmPI', money.format(piBudget));
    setText('mxmHousing', money.format(loan > 0 ? piBudget + costs : 0));
    setText('mxmTotal', money0.format(loan > 0 ? piBudget * term * 12 - loan : 0));
    setText('mxmMonthlyInc', money.format(mInc));
    setText('mxmFrontCapLabel', 'Front-end limit (' + front + '%) for housing');
    setText('mxmBackCapLabel', 'Back-end limit (' + back + '%) minus other debts');
    setText('mxmFrontCap', money.format(frontCap));
    setText('mxmBackCap', backCap < 0 ? '−' + money.format(-backCap) : money.format(backCap));
    setText('mxmBudget', money.format(Math.max(0, budget)));
    setText('mxmCosts', '−' + money.format(costs));
    setText('mxmPI2', money.format(piBudget));

    var note;
    if (backCap <= 0) note = 'Your other monthly debts already use the whole back-end limit, so these ratios leave nothing for a mortgage. Paying down debt or adding income changes this.';
    else if (piBudget <= 0) note = 'Property tax, insurance and other housing costs use up the whole housing budget, leaving nothing for loan payments.';
    else if (frontCap <= backCap) note = 'The front-end limit sets your maximum: total housing costs can be up to ' + front + '% of gross income. Your other debts are low enough not to matter.';
    else note = 'The back-end limit sets your maximum: housing plus other debts can be up to ' + back + '% of gross income. Each $100 a month of debt you pay off adds about ' +
      money0.format(maxLoan(100, rate, term)) + ' to the loan you could carry, up to the front-end limit.';
    setText('mxmBinding', note);

    var out = [];
    for (var k = -3; k <= 3; k++) {
      var r = Math.round((rate + k * 0.5) * 1000) / 1000;
      if (r < 0 || r > 30) continue;
      out.push('<tr><td>' + r + '%' + (k === 0 ? ' (yours)' : '') + '</td><td>' + money0.format(maxLoan(piBudget, r, 15)) + '</td><td>' +
        money0.format(maxLoan(piBudget, r, 20)) + '</td><td>' + money0.format(maxLoan(piBudget, r, 30)) + '</td></tr>');
    }
    el('mxmGrid').innerHTML = out.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('mxmForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
